// Pages created with the "New page" button in this browser (wiki-editor.js) are searchable here right away.
try {
    const path = decodeURIComponent(location.pathname);
    const localPages = JSON.parse(localStorage.getItem(`strawberry-wiki-local-pages:${path.slice(0, path.lastIndexOf("/") + 1)}`) || "[]");
    for (const page of Array.isArray(localPages) ? localPages : []) {
        if (
            page &&
            typeof page.title === "string" &&
            typeof page.href === "string" &&
            /^(?:new-page\.html\?[\w=&%.+-]*|(?:page|news)-[\w.-]+\.html)$/.test(page.href) &&
            !pages.some((existing) => existing.href === page.href || existing.href === page.file)
        ) {
            pages.push({ title: page.title, href: page.href, keywords: typeof page.keywords === "string" ? page.keywords : "" });
        }
    }
} catch {
    // Search still works with just the built-in page list.
}

const form = document.querySelector(".site-search");
const input = document.querySelector("#site-search-input");
const suggestions = document.querySelector("#search-suggestions");
const status = document.querySelector("#search-status");
const randomPageButton = document.querySelector("#random-page-button");

function findMatches(query) {
    const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean);

    if (terms.length === 0) {
        return [];
    }

    return pages.filter((page) => {
        const searchableText = `${page.title} ${page.keywords}`.toLowerCase();
        return terms.every((term) => searchableText.includes(term));
    });
}

function renderSuggestions() {
    const matches = findMatches(input.value);
    suggestions.replaceChildren();

    for (const page of matches) {
        const item = document.createElement("li");
        const link = document.createElement("a");
        link.href = page.href;
        link.textContent = page.title;
        item.append(link);
        suggestions.append(item);
    }

    suggestions.hidden = matches.length === 0;
    status.textContent = input.value.trim() && matches.length === 0
        ? "No matching pages found."
        : "";
}

input.addEventListener("input", renderSuggestions);

input.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
        suggestions.hidden = true;
        status.textContent = "";
    } else if (event.key === "ArrowDown" && !suggestions.hidden) {
        event.preventDefault();
        suggestions.querySelector("a")?.focus();
    }
});

// Arrow keys move through the suggestions; Escape goes back to the search box.
suggestions.addEventListener("keydown", (event) => {
    const links = [...suggestions.querySelectorAll("a")];
    const index = links.indexOf(document.activeElement);
    if (event.key === "ArrowDown") {
        event.preventDefault();
        links[Math.min(index + 1, links.length - 1)]?.focus();
    } else if (event.key === "ArrowUp") {
        event.preventDefault();
        (index <= 0 ? input : links[index - 1]).focus();
    } else if (event.key === "Escape") {
        suggestions.hidden = true;
        input.focus();
    }
});

// Hide the suggestions when clicking somewhere else on the page.
document.addEventListener("click", (event) => {
    if (!form.contains(event.target)) {
        suggestions.hidden = true;
    }
});

// Press "/" anywhere (outside a text field) to jump to the search box.
document.addEventListener("keydown", (event) => {
    const target = event.target;
    if (event.key === "/" && !event.ctrlKey && !event.metaKey &&
        !target.closest("input, textarea, select, [contenteditable='true']")) {
        event.preventDefault();
        input.focus();
    }
});

form.addEventListener("submit", (event) => {
    event.preventDefault();
    const match = findMatches(input.value)[0];

    if (match) {
        window.location.href = match.href;
    } else {
        renderSuggestions();
    }
});

randomPageButton?.addEventListener("click", () => {
    const articlePages = pages.filter((page) => page.href.startsWith("page-"));
    const randomPage = articlePages[Math.floor(Math.random() * articlePages.length)];
    window.location.href = randomPage.href;
});
